package main
import("encoding/json";"os";"path/filepath";"strings";"github.com/Hans-Einar/SDP/SDUI/go/parser")
func main(){src:=os.Args[1];out:=os.Args[2];b,e:=os.ReadFile(src);must(e);_,roots,e:=parser.Compile(string(b));must(e);var choices map[string][][]string;b,e=os.ReadFile(filepath.Join(filepath.Dir(src),"choices.json"));must(e);must(json.Unmarshal(b,&choices));must(os.MkdirAll(filepath.Join(out,"assets"),0700));for _,name:=range []string{"frame.svg","joint.svg"}{b,e=os.ReadFile(filepath.Join(filepath.Dir(src),"assets",name));must(e);must(os.WriteFile(filepath.Join(out,"assets",name),b,0600))};b,e=os.ReadFile(src);must(e);must(os.WriteFile(filepath.Join(out,"TimberFrame.sdui"),b,0600))
for _,entry:=range []string{"Analysis","Framing","Joinery","CaseParameters"}{opts:=map[string]any{};svgs:=map[string]any{};roots[entry].Walk(func(n *parser.Instance){if n.Widget=="select"{key:=n.Path[strings.LastIndex(n.Path,"/")+1:];rows,ok:=choices[key];if !ok{panic(n.Path)};items:=[]any{};for _,row:=range rows{items=append(items,map[string]any{"id":row[0],"label":row[1],"enabled":true})};opts[n.Path]=items};if n.Widget=="svg"{ref:=n.Arguments["source"].(parser.Reference);name:="frame.svg";if ref.Object=="Joint"{name="joint.svg"};svgs[n.Path]=map[string]any{"file":"assets/"+name,"width":640,"height":500}}});j:=map[string]any{"schema":"sdui-prototype-context/1","viewport":map[string]int{"width":1680,"height":1150},"choices":opts,"svg":svgs};b,e=json.MarshalIndent(j,"","  ");must(e);must(os.WriteFile(filepath.Join(out,entry+".context.json"),append(b,'\n'),0600))}}
func must(e error){if e!=nil{panic(e)}}
